import {LightningElement} from 'lwc'; import {executeMutation} from 'lightning/graphql'; export default class Probe extends LightningElement {result='pending'; async connectedCallback(){let rows=[];for(const x of [undefined,null,{}, {query:'mutation { nope }'}]) {try {let y=executeMutation(x); let kind=y&&typeof y.then==='function'?'promise':'sync';try {let v=await y;rows.push({kind,value:v===undefined?'undefined':v});} catch(e){rows.push({kind,error:String(e),name:e?.name,message:e?.message});}} catch(e){rows.push({kind:'throw',error:String(e),name:e?.name,message:e?.message});}}this.result=JSON.stringify(rows);} }